CREATE TYPE "ObservationKind" AS ENUM ('IQAIR', 'OFFICIAL_ISPU');
CREATE TYPE "ProviderState" AS ENUM ('HEALTHY', 'DEGRADED', 'UNAVAILABLE');
CREATE TABLE "UserSettings" ("id" INTEGER PRIMARY KEY DEFAULT 1, "nationalSample" JSONB NOT NULL DEFAULT '[]', "officialAllowlist" JSONB NOT NULL DEFAULT '["indonesia.go.id","klhk.go.id","bmkg.go.id","bnpb.go.id"]', "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL);
CREATE TABLE "TrackedLocation" ("id" TEXT PRIMARY KEY, "provider" TEXT NOT NULL, "city" TEXT NOT NULL, "state" TEXT, "country" TEXT NOT NULL DEFAULT 'Indonesia', "stationId" TEXT, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL, CONSTRAINT "TrackedLocation_provider_city_state_key" UNIQUE ("provider", "city", "state"));
CREATE TABLE "AirObservation" ("id" TEXT PRIMARY KEY, "provider" TEXT NOT NULL, "providerId" TEXT, "kind" "ObservationKind" NOT NULL, "metric" TEXT NOT NULL, "value" INTEGER NOT NULL, "category" TEXT, "period" TEXT, "city" TEXT NOT NULL, "region" TEXT, "station" TEXT, "sourceUrl" TEXT NOT NULL, "observedAt" TIMESTAMP(3) NOT NULL, "fetchedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "metadata" JSONB, CONSTRAINT "AirObservation_provider_providerId_metric_observedAt_key" UNIQUE ("provider", "providerId", "metric", "observedAt"));
CREATE INDEX "AirObservation_city_fetchedAt_idx" ON "AirObservation"("city", "fetchedAt");
CREATE TABLE "HourlyDispatch" ("id" TEXT PRIMARY KEY, "hourBucket" TIMESTAMP(3) NOT NULL UNIQUE, "status" TEXT NOT NULL DEFAULT 'SENDING', "sentAt" TIMESTAMP(3), "error" TEXT, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE "ProviderHealth" ("provider" TEXT PRIMARY KEY, "state" "ProviderState" NOT NULL DEFAULT 'UNAVAILABLE', "lastSuccessAt" TIMESTAMP(3), "lastFailureAt" TIMESTAMP(3), "errorSummary" TEXT, "updatedAt" TIMESTAMP(3) NOT NULL);
CREATE TABLE "NewsCache" ("id" TEXT PRIMARY KEY, "topic" TEXT NOT NULL UNIQUE, "content" JSONB NOT NULL, "fetchedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "expiresAt" TIMESTAMP(3) NOT NULL);
CREATE TABLE "SourceCandidate" ("id" TEXT PRIMARY KEY, "agency" TEXT NOT NULL, "domain" TEXT NOT NULL, "details" JSONB NOT NULL, "confidenceScore" INTEGER NOT NULL, "recommendation" TEXT NOT NULL, "reviewedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE "ApprovedSource" ("id" TEXT PRIMARY KEY, "candidateId" TEXT NOT NULL UNIQUE, "approvedBy" TEXT NOT NULL, "approvedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "config" JSONB NOT NULL);
CREATE TABLE "ProviderQuotaUsage" ("id" TEXT PRIMARY KEY, "provider" TEXT NOT NULL, "bucket" TIMESTAMP(3) NOT NULL, "count" INTEGER NOT NULL DEFAULT 0, CONSTRAINT "ProviderQuotaUsage_provider_bucket_key" UNIQUE ("provider", "bucket"));
